using System.Collections.Immutable;
using System.Text;
using Airlock.Domain.Targets;
using Airlock.Domain.Text;

namespace Airlock.Domain.Intelligence;

/// <summary>Where a candidate CPE came from: the official CPE dictionary, or a guess generated by Syft.</summary>
public enum CpeSource
{
    Dictionary,
    Generated,
}

/// <summary>A CPE proposed for a package (GLOSSARY: Candidate CPE).</summary>
public sealed record CandidateCpe
{
    private const string Prefix = "cpe:2.3:";
    private const int VendorComponent = 3;
    private const int ProductComponent = 4;

    public CandidateCpe(string value, CpeSource source)
    {
        Value = DomainText.Require(value, DomainLimits.Cpe, nameof(value));
        if (!Value.StartsWith(Prefix, StringComparison.Ordinal))
        {
            throw new ArgumentException("Must start with \"cpe:2.3:\".", nameof(value));
        }

        if (!Enum.IsDefined(source))
        {
            throw new ArgumentOutOfRangeException(nameof(source));
        }

        Source = source;
        Vendor = Component(Value, VendorComponent);
        Product = Component(Value, ProductComponent);
    }

    public string Value { get; }

    public CpeSource Source { get; }

    public string Vendor { get; }

    public string Product { get; }

    // BR-08: dictionary candidates; then guesses whose vendor and product equal the package name; then guesses whose
    // product does; then the rest — Syft's order within each tier, exact duplicates dropped, at most `max`.
    public static IReadOnlyList<CandidateCpe> Prioritize(Package package, IEnumerable<CandidateCpe> candidates, int max = 3)
    {
        ArgumentNullException.ThrowIfNull(package);
        ArgumentNullException.ThrowIfNull(candidates);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(max);

        var name = ProductName.ComparisonKey(package.Name);
        var seen = new HashSet<string>(StringComparer.Ordinal);
        var unique = new List<CandidateCpe>();
        foreach (var candidate in candidates)
        {
            ArgumentNullException.ThrowIfNull(candidate, nameof(candidates));
            if (seen.Add(candidate.Value))
            {
                unique.Add(candidate);
            }
        }

        return unique
            .Select((candidate, index) => (Candidate: candidate, Index: index, Tier: Tier(candidate, name)))
            .OrderBy(entry => entry.Tier)
            .ThenBy(entry => entry.Index)
            .Take(max)
            .Select(entry => entry.Candidate)
            .ToImmutableArray();
    }

    private static int Tier(CandidateCpe candidate, string name)
    {
        if (candidate.Source == CpeSource.Dictionary)
        {
            return 0;
        }

        var productMatches = ProductName.ComparisonKey(candidate.Product) == name;
        if (productMatches && ProductName.ComparisonKey(candidate.Vendor) == name)
        {
            return 1;
        }

        return productMatches ? 2 : 3;
    }

    /// <summary>The component at <paramref name="index"/>, split on unescaped colons, with escapes removed.</summary>
    private static string Component(string cpe, int index)
    {
        var current = 0;
        var builder = new StringBuilder();
        for (var i = 0; i < cpe.Length; i++)
        {
            var c = cpe[i];
            if (c == '\\' && i + 1 < cpe.Length)
            {
                if (current == index)
                {
                    builder.Append(cpe[i + 1]);
                }

                i++;
            }
            else if (c == ':')
            {
                if (current == index)
                {
                    break;
                }

                current++;
            }
            else if (current == index)
            {
                builder.Append(c);
            }
        }

        return current == index ? builder.ToString() : string.Empty;
    }
}
